/**
 * Ticket #22 acceptance test — the contract for the resolution warning and the grip marker.
 * Do not edit this file to make it pass.
 */
import { describe, expect, it } from 'vitest';
import {
  fitCells,
  fitPoint,
  nativeBlockSize,
  parseSpec,
  removeMarker,
  resolutionIssues,
  type FitCellsOptions,
} from '../../scripts/lib/gemini-art';
import type { PngImage } from '../../scripts/lib/png';

type Pixel = readonly [number, number, number, number];
const CLEAR: Pixel = [0, 0, 0, 0];
const BLUE: Pixel = [0, 0, 200, 255];
const CYAN: Pixel = [0, 255, 255, 255];
const SEAM: Pixel = [20, 27, 27, 255];
const COLOURS: readonly Pixel[] = [
  [242, 234, 241, 255],
  [184, 220, 229, 255],
  [45, 105, 123, 255],
  [59, 54, 67, 255],
  [252, 226, 202, 255],
];

function canvas(width: number, height: number): PngImage {
  const data = Buffer.alloc(width * height * 4);
  for (let i = 0; i < width * height; i += 1) data.set(CLEAR, i * 4);
  return { width, height, data };
}

function rect(image: PngImage, x0: number, y0: number, w: number, h: number, p: Pixel): void {
  for (let y = y0; y < y0 + h; y += 1) for (let x = x0; x < x0 + w; x += 1) image.data.set(p, (y * image.width + x) * 4);
}

function pixel(image: PngImage, x: number, y: number): number[] {
  return Array.from(image.data.subarray((y * image.width + x) * 4, (y * image.width + x) * 4 + 4));
}

/**
 * A sprite of `bw × bh` blocks of `b × b` px, its top-left at (ox, oy). Neighbouring blocks
 * often share a colour, so shapes span several blocks. When `seams` is set, some blocks get
 * a 1 px column of another colour on their left edge, like Gemini's anti-alias remnants.
 */
function blocky(image: PngImage, b: number, ox: number, oy: number, bw: number, bh: number, seams: boolean): void {
  for (let by = 0; by < bh; by += 1) {
    for (let bx = 0; bx < bw; bx += 1) {
      const colour = COLOURS[(bx * bx * 7 + by * 31 + bx * by) % COLOURS.length]!;
      rect(image, ox + bx * b, oy + by * b, b, b, colour);
      if (seams && bx % 3 === 0 && by % 2 === 0) rect(image, ox + bx * b, oy + by * b, 1, b, SEAM);
    }
  }
}

describe('#22 nativeBlockSize', () => {
  for (const [b, ox, oy] of [
    [8, 5, 11],
    [16, 0, 0],
    [16, 7, 3],
    [32, 13, 29],
  ] as const) {
    it(`finds ${b} px blocks at offset (${ox}, ${oy}), with seams`, () => {
      const image = canvas(512, 512);
      blocky(image, b, ox, oy, Math.floor((512 - ox) / b) - 1, Math.floor((512 - oy) / b) - 1, true);
      expect(nativeBlockSize(image)).toBe(b);
    });
  }

  it('finds the block size without seams too', () => {
    const image = canvas(512, 512);
    blocky(image, 16, 4, 4, 30, 30, false);
    expect(nativeBlockSize(image)).toBe(16);
  });
});

describe('#22 resolutionIssues', () => {
  /** Four direction columns of one 512 px cell each, a 10-block-wide sprite of `tall` 16 px blocks per cell. */
  function sheet(tall: number): PngImage {
    const image = canvas(2048, 512);
    for (let column = 0; column < 4; column += 1) blocky(image, 16, column * 512 + 100, 512 - 8 - tall * 16, 10, tall, true);
    return image;
  }

  it('warns once per direction when the sprite has far more blocks than its fitted height', () => {
    const issues = resolutionIssues(sheet(29), 4, 1, [15, 15]);
    expect(issues.map((issue) => [issue.kind, issue.column])).toEqual([
      ['resolution', 0],
      ['resolution', 1],
      ['resolution', 2],
      ['resolution', 3],
    ]);
    for (const issue of issues) {
      expect(issue.detail).toMatch(/29 blocks/);
      expect(issue.detail).toMatch(/15 px/);
    }
  });

  it('stays quiet when the blocks roughly match the fitted pixels', () => {
    expect(resolutionIssues(sheet(16), 4, 1, [15, 15])).toEqual([]);
  });
});

describe('#22 grip marker', () => {
  /** Four 64 px cells, a 32 px blue sprite in each; cyan 3×3 markers in cells 0–2, none in cell 3. */
  function source(): PngImage {
    const image = canvas(256, 64);
    for (let column = 0; column < 4; column += 1) rect(image, column * 64 + 16, 16, 32, 32, BLUE);
    rect(image, 21, 41, 3, 3, CYAN); // inside the sprite
    rect(image, 64 + 41, 17, 3, 3, CYAN); // inside the sprite, another corner
    rect(image, 128 + 2, 2, 3, 3, CYAN); // on the backdrop
    return image;
  }
  const FIT: FitCellsOptions = {
    columns: 4,
    rows: 1,
    frameWidth: 16,
    frameHeight: 16,
    anchor: 'center',
    share: 'sheet',
  };

  it('returns each cell’s marker centre in source pixels, null when a cell has none', () => {
    const { centres } = removeMarker(source(), [0, 255, 255], 4, 1);
    expect(centres).toEqual([[22.5, 42.5], [106.5, 18.5], [131.5, 3.5], null]);
  });

  it('removes the marker: sprite colour inside the sprite, transparent on the backdrop', () => {
    const { image } = removeMarker(source(), [0, 255, 255], 4, 1);
    expect(pixel(image, 22, 42)).toEqual([...BLUE]);
    expect(pixel(image, 64 + 42, 18)).toEqual([...BLUE]);
    expect(pixel(image, 128 + 3, 3)[3]).toBe(0);
    for (let i = 0; i < image.data.length; i += 4) {
      const isCyan = image.data[i] === 0 && image.data[i + 1] === 255 && image.data[i + 2] === 255;
      expect(isCyan && image.data[i + 3]! > 0).toBe(false);
    }
  });

  it('maps a marker centre to the output pixel containing it, clamped inside the frame', () => {
    const { image, centres } = removeMarker(source(), [0, 255, 255], 4, 1);
    // The sprite (16..48 in each cell) fills the 16 px frame at scale 0.5.
    expect(fitPoint(image, FIT, centres[0]!)).toEqual([3, 13]);
    expect(fitPoint(image, FIT, centres[1]!)).toEqual([13, 1]);
    expect(fitPoint(image, FIT, centres[2]!)).toEqual([0, 0]);
  });

  it('leaves the fitted sprite as if there had been no marker inside it', () => {
    const plain = canvas(256, 64);
    for (let column = 0; column < 4; column += 1) rect(plain, column * 64 + 16, 16, 32, 32, BLUE);
    const { image } = removeMarker(source(), [0, 255, 255], 4, 1);
    expect(Buffer.compare(fitCells(image, FIT).data, fitCells(plain, FIT).data)).toBe(0);
  });

  it('reads gripMarker from an attachment spec and rejects a bad colour', () => {
    const asset = {
      key: 'attachment.sword-back',
      kind: 'attachment',
      source: 'art-source/gemini/x.png',
      sheet: 'generated/x/sword.png',
      frameWidth: 16,
      frameHeight: 16,
      layout: 'grid',
      directions: ['down', 'up', 'left', 'right'],
      frames: 1,
      slot: 'back',
    };
    expect(parseSpec({ assets: [{ ...asset, gripMarker: '#00ffff' }] }).assets[0]!.gripMarker).toEqual([0, 255, 255]);
    expect(() => parseSpec({ assets: [{ ...asset, gripMarker: 'cyan' }] })).toThrow(/gripMarker/);
  });
});
